    Message.print(FileReader.MODULE, "Container has " + this._container.getPartCount() + " parts");
    Message.print(FileReader.MODULE, "Loading " + this._fileRecord.getLevelCount() + " levels and " + this._fileRecord.getAttributeCount() + " attributes");
    let fileContents = new ContentLoader(this._fileStorage, this._fileName);
    let prefetchLevelIndex = this._fileRecord.getLevelCount() - 6;
    if (prefetchLevelIndex < 0)
      prefetchLevelIndex = 0;
    if (lazyLoading == false)
      prefetchLevelIndex = 0;
