      let name = parts.get(Registry._COL_UNIT_NAME);
      let type = parts.get(Registry._COL_UNIT_TYPE);
      let targetUnitCode = Numbers.getInteger(parts.get(Registry._COL_UNIT_TARGET_CODE), 0);
      let b = Numbers.getDouble(parts.get(Registry._COL_UNIT_FACTOR_B), 0);
      let c = Numbers.getDouble(parts.get(Registry._COL_UNIT_FACTOR_C), 0);
      let abbreviation = parts.get(Registry._COL_UNIT_ABBREVIATION);
