class WellKnownTextNode {
  /** Get the name */
  _name;
  /** Get the arguments */
  _argumentList;
  /**
   * Create a new node.
   * @param name the name.
   * @param argumentList the arguments.
   */
  constructor(name, argumentList) {
    if (argumentList == null)
      argumentList = new AList();
    this._name = name;
    this._argumentList = argumentList;
  }
  /**
   * Get the name.
   * @return the name.
   */
  getName() {
    return this._name;
  }
  /**
   * Get the arguments.
   * @return the arguments.
   */
  getArguments() {
    return this._argumentList;
  }
  /**
   * Add an argument.
   * @param argument the argument to add.
   */
  addArgument(argument) {
    this._argumentList.add(argument);
  }
  /**
   * Get an argument.
   * @param index the index of the argument.
   * @return the argument.
   */
  getArgument(index) {
    return this._argumentList.get(index);
  }
  /**
   * Get an optional argument.
   * @param index the index of the argument.
   * @return the argument.
   */
  getOptionalArgument(index) {
    if (index < this._argumentList.size())
      return this.getArgument(index);
    return null;
  }
  /**
   * Get arguments by name.
   * @param name the name of the arguments.
   * @return the arguments.
   */
  getArgumentsByName(name) {
    let list = new AList();
    for (let argument of this._argumentList)
      if (Strings.equalsIgnoreCase(argument.getName(), name))
        list.add(argument);
    return list;
  }
  /**
   * Get an argument by name.
   * @param name the name of the argument.
   * @return the argument (null if not found).
   */
  getArgumentByName(name) {
    let list = this.getArgumentsByName(name);
    return list.size() == 0 ? null : list.get(0);
  }
  /**
   * Parse an expression.
   * @param expression the expression.
   * @return the parsed expression.
   */
  static parse(expression) {
    if (Strings.getLength(expression) >= 2 && Strings.startsWith(expression, '"') && Strings.endsWith(expression, '"'))
      return new WellKnownTextNode(expression, null);
    let index1 = Strings.indexOf(expression, "[");
    if (index1 < 0)
      index1 = Strings.indexOf(expression, "(");
    if (index1 < 0)
      return new WellKnownTextNode(expression, null);
    let index2 = Strings.lastIndexOf(expression, "]");
    if (index2 < 0)
      index2 = Strings.lastIndexOf(expression, ")");
    ASystem.assertNot(index2 < 0, "Invalid well-known-text '" + expression + "' (missing closing bracket)");
    ASystem.assertNot(index2 < index1, "Invalid well-known-text '" + expression + "' (wrong bracket sequence)");
    let argumentList = Strings.substring(expression, index1 + 1, index2);
    let arguments1 = Strings.splitAdvanced(
      argumentList,
      ",",
      "[(",
      "])",
      '"'
      /*literals*/
    );
    let arguments2 = new AList();
    for (let i = 0; i < arguments1.size(); i++)
      arguments2.add(WellKnownTextNode.parse(Strings.trim(arguments1.get(i))));
    let name = Strings.trim(Strings.substring(expression, 0, index1));
    return new WellKnownTextNode(name, arguments2);
  }
}
