    let toWGS84s = new AList();
    WellKnownText.parseAngularUnit(node.getArgumentByName("UNIT"), dialect);
    node.getArgumentsByName("AXIS");
    let authority = node.getArgumentByName("AUTHORITY");
    let epsgCode = WellKnownText.getEPSGCode(authority, dialect);
    let code = epsgCode == 0 ? crsCode : epsgCode;
    if (toWGS84m != null)
      toWGS84s.add(new Operation(0, "", Operation.TRANSFORMATION, code, CRS.WGS84_2D_CRS_CODE, 0, toWGS84m));
