    let epsgCode = WellKnownText.getEPSGCode(authority, dialect);
    let code = epsgCode == 0 ? crsCode : epsgCode;
    let projectionOperation = new Operation(0, "", Operation.CONVERSION, code, baseCRS.getCode(), 0, projectionMethod);
